#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, m, k;
    if(scanf("%d %d %d", &n, &m, &k) != 3) return 0;
    vector<int> P(k+1);
    for(int i = 1; i <= k; i++) scanf("%d", &P[i]);

    vector<int> eu(m), ev(m), es(m);
    vector<vector<int>> bySys(k+1);
    for(int j = 0; j < m; j++){
        scanf("%d %d %d", &eu[j], &ev[j], &es[j]);
        bySys[es[j]].push_back(j);
    }

    // Model: nodes = stations [0..n-1] + one node per connected component of each system's subgraph.
    // For edge (u,v,t) in component node cn: u->cn cost P_t (enter), v->cn cost P_t, cn->u cost 0 (exit), cn->v cost 0.
    vector<int> stamp(n+1, 0), localArr(n+1, 0);
    int counter = n; // next component node id

    vector<int> fromArr, toArr, wArr;
    fromArr.reserve(4*(size_t)m);
    toArr.reserve(4*(size_t)m);
    wArr.reserve(4*(size_t)m);

    vector<int> parent, rootToNode;

    for(int t = 1; t <= k; t++){
        auto &edg = bySys[t];
        if(edg.empty()) continue;
        int cnt = 0;
        vector<int> lu(edg.size()), lv(edg.size());
        for(size_t idx = 0; idx < edg.size(); idx++){
            int j = edg[idx];
            int u = eu[j], v = ev[j];
            if(stamp[u] != t){ stamp[u] = t; localArr[u] = cnt++; }
            if(stamp[v] != t){ stamp[v] = t; localArr[v] = cnt++; }
            lu[idx] = localArr[u]; lv[idx] = localArr[v];
        }
        parent.resize(cnt);
        for(int i = 0; i < cnt; i++) parent[i] = i;
        auto find = [&](int x){
            while(parent[x] != x){
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        for(size_t idx = 0; idx < edg.size(); idx++){
            int a = find(lu[idx]), b = find(lv[idx]);
            if(a != b) parent[a] = b;
        }
        rootToNode.assign(cnt, -1);
        for(size_t idx = 0; idx < edg.size(); idx++){
            int j = edg[idx];
            int r = find(lu[idx]);
            if(rootToNode[r] == -1) rootToNode[r] = counter++;
            int cn = rootToNode[r];
            int u0 = eu[j]-1, v0 = ev[j]-1;
            fromArr.push_back(u0); toArr.push_back(cn); wArr.push_back(P[t]);
            fromArr.push_back(v0); toArr.push_back(cn); wArr.push_back(P[t]);
            fromArr.push_back(cn); toArr.push_back(u0); wArr.push_back(0);
            fromArr.push_back(cn); toArr.push_back(v0); wArr.push_back(0);
        }
    }

    int numNodes = counter;
    int E = (int)fromArr.size();
    vector<int> head(numNodes+1, 0);
    for(int i = 0; i < E; i++) head[fromArr[i]+1]++;
    for(int i = 0; i < numNodes; i++) head[i+1] += head[i];
    vector<int> toC(E), wC(E);
    {
        vector<int> pos(head.begin(), head.end()-1);
        for(int i = 0; i < E; i++){
            toC[pos[fromArr[i]]] = toArr[i];
            wC[pos[fromArr[i]]] = wArr[i];
            pos[fromArr[i]]++;
        }
    }

    int A, B;
    scanf("%d %d", &A, &B);

    const long long INF = (long long)1e18;
    vector<long long> dist(numNodes, INF);
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
    dist[A-1] = 0;
    pq.push(make_pair(0LL, A-1));
    while(!pq.empty()){
        pair<long long,int> top = pq.top(); pq.pop();
        long long d = top.first;
        int u = top.second;
        if(d > dist[u]) continue;
        for(int e = head[u]; e < head[u+1]; e++){
            int v = toC[e];
            long long nd = d + wC[e];
            if(nd < dist[v]){
                dist[v] = nd;
                pq.push(make_pair(nd, v));
            }
        }
    }

    if(dist[B-1] >= INF) puts("-1");
    else printf("%lld\n", dist[B-1]);
    return 0;
}
